(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.KANA_META_CORE=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
function clone(value){return JSON.parse(JSON.stringify(value));}
function emptyState(){return{schemaVersion:1,items:{},cemetery:[],nemeses:{},portugueseEvents:[],events:[],bosses:{boundary:{attempts:0,best:0,completedAt:null}},achievements:[]};}
function base(state){return{...emptyState(),...(state||{}),items:{...(state?.items||{})},nemeses:{...(state?.nemeses||{})},bosses:{...emptyState().bosses,...(state?.bosses||{})}};}
function dayKey(at){return new Date(at||Date.now()).toISOString().slice(0,10);}
function difficulty(stat={},correct=false,at=Date.now()){const next={...stat,attempts:Number(stat.attempts||0)+1,hits:Number(stat.hits||0),errors:Number(stat.errors||0),streak:Number(stat.streak||0),cursed:Boolean(stat.cursed),curseBrokenAt:stat.curseBrokenAt||null,days:[...new Set([...(stat.days||[]),dayKey(at)])]};if(correct){next.hits++;next.streak++;}else{next.errors++;next.streak=0;}const rate=next.errors/next.attempts;let event=null;if(!next.cursed&&next.attempts>=8&&next.errors>=4&&rate>=.45){next.cursed=true;event='curse_started';}else if(next.cursed&&next.streak>=5&&rate<.3){next.cursed=false;next.curseBrokenAt=at;event='curse_broken';}return{stat:next,event};}
function addEvent(state,type,payload={},at=Date.now()){state.events=[{id:`${type}:${at}:${payload.key||''}`,type,at,...payload},...(state.events||[])].slice(0,80);}
function achievement(state,id,title,at=Date.now()){if(state.achievements.some(item=>item.id===id))return;state.achievements.push({id,title,at});addEvent(state,'achievement',{key:id,title},at);}
function itemIdentity(event){const raw=event.item||{},display=raw.written||raw.lemma||raw[0]||raw.text||raw.prompt||raw.id||event.contentId;return{key:`${event.mode}:${raw.id||raw[0]||event.contentId}`,display,reading:raw.reading||raw.lemmaReading||'',mode:event.mode};}
function recordAttempt(state,event){const next=base(clone(state||emptyState())),identity=itemIdentity(event),before=next.items[identity.key]||identity,updated=difficulty(before,event.correct,event.at);next.items[identity.key]={...before,...identity,...updated.stat,lastAt:event.at};if(updated.event){addEvent(next,updated.event,{key:identity.key,display:identity.display},event.at);if(updated.event==='curse_broken')achievement(next,'first-curse-broken','Primeira maldição quebrada',event.at);}if(event.requiresPortuguese===false)next.portugueseEvents=[...(next.portugueseEvents||[]),{correct:Boolean(event.correct),requiresPortuguese:false,mode:event.mode,at:event.at}].slice(-2000);refreshNemesis(next,identity.key,event.at);return next;}
function recordDeath(state,death){const next=base(clone(state||emptyState())),key=`${death.mode}:${death.itemId}`,found=next.cemetery.find(item=>item.key===key);if(found){found.deaths++;found.lastAt=death.at;found.longestRun=Math.max(found.longestRun||0,death.runLength||0);found.lastAnswer=death.answer??found.lastAnswer;}else next.cemetery.push({key,itemId:death.itemId,display:death.display,reading:death.reading||'',mode:death.mode,deaths:1,firstAt:death.at,lastAt:death.at,longestRun:death.runLength||0,lastAnswer:death.answer??null});const item=next.items[key]||{key,mode:death.mode,display:death.display,reading:death.reading||'',attempts:0,hits:0,errors:0,days:[]};item.runDeaths=Number(item.runDeaths||0)+1;item.errors=Math.max(Number(item.errors||0),item.runDeaths);item.days=[...new Set([...(item.days||[]),dayKey(death.at)])];next.items[key]=item;refreshNemesis(next,key,death.at);addEvent(next,'run_death',{key,display:death.display,mode:death.mode,runLength:death.runLength||0},death.at);return next;}
function refreshNemesis(state,key,at){const item=state.items[key];if(!item)return;const qualifies=Number(item.runDeaths)>=3&&Number(item.errors)>=8&&Number(item.days?.length)>=2;if(qualifies&&!state.nemeses[key]){state.nemeses[key]={key,display:item.display,reading:item.reading,mode:item.mode,runDeaths:item.runDeaths,errors:item.errors,createdAt:at};achievement(state,'first-nemesis','Primeira Nemesis',at);addEvent(state,'nemesis_created',{key,display:item.display},at);}else if(state.nemeses[key])state.nemeses[key]={...state.nemeses[key],runDeaths:item.runDeaths,errors:item.errors};}
function dependency(events=[]){const direct=events.filter(event=>event?.requiresPortuguese===false);if(!direct.length)return{value:null,evidence:0,label:'não avaliada'};const success=direct.filter(event=>event.correct).length;return{value:Math.round((1-success/direct.length)*100),evidence:direct.length,label:'métrica interna'};}
function scoreEntries(entries){const values=entries.filter(([,s])=>Number(s.attempts)>0).map(([,s])=>Math.min(100,Math.round(Number(s.mastery||0)/5*100)));return values.length?Math.round(values.reduce((a,b)=>a+b,0)/values.length):null;}
function profile(state,skills={},vocabulary={}){const groups={hiragana:[],katakana:[],kanji:[],grammar:[],listening:[],reading:[]};for(const [key,value]of Object.entries(skills)){const mode=key.split(':')[0],group=mode==='fracture'?'grammar':mode==='void'?'listening':mode==='labyrinth'?'reading':mode;if(groups[group])groups[group].push([key,value]);}const vocab=scoreEntries(Object.entries(vocabulary));return{hiragana:scoreEntries(groups.hiragana),katakana:scoreEntries(groups.katakana),kanji:scoreEntries(groups.kanji),vocabulary:vocab,grammar:scoreEntries(groups.grammar),listening:scoreEntries(groups.listening),reading:scoreEntries(groups.reading),portugueseDependency:dependency(state.portugueseEvents),cursed:Object.values(state.items).filter(item=>item.cursed),nemeses:Object.values(state.nemeses),cemetery:[...state.cemetery].sort((a,b)=>b.lastAt-a.lastAt)};}
function bossMetrics(state,skills={},vocabulary={}){const all=[...Object.values(skills),...Object.values(vocabulary)],attempts=all.reduce((sum,item)=>sum+Number(item.attempts||0),0),territories=new Set(Object.keys(skills).filter(key=>Number(skills[key].attempts)>0).map(key=>key.split(':')[0]));if(Object.values(vocabulary).some(item=>Number(item.attempts)>0))territories.add('vocabulary');return{attempts,territories:territories.size,unlocked:attempts>=100&&territories.size>=3};}
const BOUNDARY=[
 {id:'b1',territory:'hiragana',prompt:'きょ',question:'Leitura',choices:['kyo','kya','sho'],answer:'kyo'},
 {id:'b2',territory:'katakana',prompt:'コンビニ',question:'Conceito',choices:['loja de conveniência','hotel','restaurante'],answer:'loja de conveniência'},
 {id:'b3',territory:'kanji',prompt:'火山',question:'Conceito',choices:['vulcão','oceano','floresta'],answer:'vulcão'},
 {id:'b4',territory:'vocabulary',prompt:'飲む',question:'Conceito',choices:['beber','comer','dormir'],answer:'beber'},
 {id:'b5',territory:'grammar',prompt:'図書館＿勉強します。',question:'Partícula',choices:['で','に','を'],answer:'で'},
 {id:'b6',territory:'listening',prompt:'駅はどこですか',audio:true,question:'O que foi dito?',choices:['Onde fica a estação?','Quando sai o trem?','Onde fica a escola?'],answer:'Onde fica a estação?'},
 {id:'b7',territory:'reading',prompt:'ねこは机の下にいます。',question:'ねこはどこにいますか。',choices:['机の下','庭','いすの上'],answer:'机の下'}
];
function finishBoss(state,hits,at=Date.now()){const next=base(clone(state)),boss=next.bosses.boundary;boss.attempts++;boss.best=Math.max(boss.best||0,hits);if(hits>=6&&!boss.completedAt){boss.completedAt=at;achievement(next,'first-boss','Primeiro Boss derrotado',at);addEvent(next,'boss_defeated',{key:'boundary',title:'境界'},at);}return next;}
return{emptyState,recordAttempt,recordDeath,dependency,profile,bossMetrics,BOUNDARY,finishBoss};
});
